public static boolean computeWithTwoHashMaps(String s, String t) {
    if (s.length() != t.length()) {
        return false;
    }

    Map<Character, Character> mapST = new HashMap<>();
    Map<Character, Character> mapTS = new HashMap<>();

    for (int i = 0; i < s.length(); i++) {
        char c1 = s.charAt(i);
        char c2 = t.charAt(i);

        if (mapST.containsKey(c1) && mapST.get(c1) != c2) {
            return false;
        }
        if (mapTS.containsKey(c2) && mapTS.get(c2) != c1) {
            return false;
        }

        mapST.put(c1, c2);
        mapTS.put(c2, c1);
    }
    return true;
}

public static boolean computeWithHashMapHashSet(String s, String t) {
    if (s.length() != t.length()) {
        return false;
    }

    Map<Character, Character> map = new HashMap<>();
    Set<Character> used = new HashSet<>();

    for (int i = 0; i < s.length(); i++) {
        char c1 = s.charAt(i);
        char c2 = t.charAt(i);

        if (map.containsKey(c1)) {
            if (map.get(c1) != c2) {
                return false;
            }
        } else {
            if (used.contains(c2)) {
                return false;
            }
            map.put(c1, c2);
            used.add(c2);
        }
    }
    return true;
}

public static boolean computeWithArray(String s, String t) {
    if (s.length() != t.length()) {
        return false;
    }

    int[] mapST = new int[256];
    int[] mapTS = new int[256];

    for (int i = 0; i < s.length(); i++) {
        char c1 = s.charAt(i);
        char c2 = t.charAt(i);

        if (mapST[c1] != 0 && mapST[c1] != c2) {
            return false;
        }
        if (mapTS[c2] != 0 && mapTS[c2] != c1) {
            return false;
        }

        mapST[c1] = c2;
        mapTS[c2] = c1;
    }
    return true;
}
